+const roles = ["viewer", "cook", "manager"];
+
+function authenticate(store, headers) {
+  const authorization = Object.entries(headers).find(([name]) => name.toLowerCase() === "authorization")?.[1];
+  const token = typeof authorization === "string" && /^Bearer +([^\s]+)$/i.exec(authorization)?.[1];
+  const key = token && store.data.apiKeys.find((entry) => entry.key === token);
+  if (!key) throw new AppError("unauthorized");
+  return key;
+}

